package com.codenzic.workspace.eod.domain; import jakarta.persistence.*; import lombok.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="eod_reports",uniqueConstraints=@UniqueConstraint(columnNames={"employee_id","report_date"})) @Getter @NoArgsConstructor public class EodReport { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @Column(nullable=false) UUID organizationId; @Column(nullable=false) UUID employeeId; @Column(nullable=false) LocalDate reportDate; @Column(nullable=false,length=3000) String summary; @Column(length=2000) String blockers; @Column(nullable=false,length=20) String status="DRAFT"; Instant submittedAt; UUID reviewedBy; Instant reviewedAt; @Column(length=1000) String reviewComment; public EodReport(UUID o,UUID e,LocalDate d,String s,String b){organizationId=o;employeeId=e;reportDate=d;summary=s;blockers=b;} public void updateDraft(String summary,String blockers){if(!status.equals("DRAFT"))throw new IllegalStateException("Only draft reports can be updated");this.summary=summary;this.blockers=blockers;} public void submit(){if(!status.equals("DRAFT"))throw new IllegalStateException("Only draft reports can be submitted");status="SUBMITTED";submittedAt=Instant.now();} public void review(String next,UUID reviewer,String comment){if(!status.equals("SUBMITTED"))throw new IllegalStateException("Only submitted reports can be reviewed");status=next;reviewedBy=reviewer;reviewedAt=Instant.now();reviewComment=comment;}}
